from fastmcp import FastMCP

mcp = FastMCP("config-server")

@mcp.resource("data://config")
def get_config() -> dict:
    """Return static configuration."""
    return {
        "app_name": "example",
        "version": "1.0.0",
        "debug": True,
        "features": {
            "auth": True,
            "logging": True,
            "caching": False
        }
    }

if __name__ == "__main__":
    mcp.run()
